package vn.nanase.hako.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;
import vn.nanase.hako.*;import org.json.*;

/** Offline tests of real feature paths, no web credentials or device assumptions. */
public final class FeatureFlowTest extends Instrumentation {
 int checks;MainActivity activity;
 void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);Bundle b=new Bundle();b.putString("stream","PASS "+label+"\n");sendStatus(0,b);}
 Object field(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 void call(String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);runOnMainSync(()->{try{m.invoke(activity,args);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();}
 View find(View root,String label){if(root instanceof TextView&&label.equals(((TextView)root).getText().toString()))return root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){View match=find(((ViewGroup)root).getChildAt(n),label);if(match!=null)return match;}return null;}
 void waitFor(Callable<Boolean> ready)throws Exception{long end=SystemClock.elapsedRealtime()+6000;while(!ready.call()&&SystemClock.elapsedRealtime()<end){SystemClock.sleep(25);waitForIdleSync();}}
 void clearDatabase(Store store,Context c){synchronized(store){for(String table:new String[]{"books","chapters","read_chapters"})store.getWritableDatabase().delete(table,null,null);store.resetDerived();}LibraryState.resetForImport();Store.delete(store.cache);Store.delete(new File(c.getFilesDir(),"toc-state"));Store.delete(new File(c.getFilesDir(),"library-state.json"));Store.delete(new File(c.getFilesDir(),"library-delta.json"));}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();CountDownLatch release=new CountDownLatch(1);try{
  Context ctx=getTargetContext();Store s=Store.get(ctx);SharedPreferences p=ctx.getSharedPreferences("settings",0);p.edit().putBoolean("sync_paused",true).putBoolean("charging",false).putString("origin","https://invalid.example").commit();HakoParser.ORIGIN="https://invalid.example";
  String id="truyen-999009",base="https://invalid.example/truyen/999009-fixture",current=id+"-2",future=id+"-3";
  String infoHtml="<h1 class='series-name'>Thông tin mẫu</h1><div class='summary-content'>Giới thiệu riêng của bộ truyện.</div><div class='series-information'><div class='info-item'><span class='info-name'>Tình trạng:</span><span class='info-value'>Đã hoàn thành</span></div><div class='info-item'>Cập nhật cuối: <time datetime='2026-10-01T10:00:00Z'>01/10/2026</time></div></div><main><a href='"+base+"/c2-old'>Chương cũ</a><a href='"+base+"/c3-new'>Chương mới</a></main>";
  StoryInfo info=StoryInfo.parse(infoHtml,base);check(info.chapters==2&&info.status.equals("Đã hoàn thành")&&info.updatedAt>0&&info.summary.contains("Giới thiệu"),"Story detail parser separates synopsis site status total and update time");info.save(ctx);check(StoryInfo.load(ctx,id).summary.equals(info.summary),"Story information atomic cache roundtrip");
  s.putBook(new HakoParser.Link(id,"Feature fixture",base));s.catalog(id,Arrays.asList(new HakoParser.Link(id+"-1","Tập 1 · Minh họa",base+"/c1-art"),new HakoParser.Link(current,"Tập 1 · Chương cũ",base+"/c2-old"),new HakoParser.Link(future,"Tập 1 · Chương mới",base+"/c3-new")));s.position(id,current,0,0);s.pin(id,true);s.setKeepFull(id,true);
  StringBuilder content=new StringBuilder();for(int n=0;n<120;n++)content.append("<p>Đoạn văn dùng để kiểm tra trình đọc độc lập với hàng đợi web đang chờ.</p>");Store.write(s.html(current),content.toString());s.state(current,true,"");s.readable(current);LibraryState.refresh(ctx);
  activity=(MainActivity)startActivitySync(new Intent().setClassName(ctx.getPackageName(),"vn.nanase.hako.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
  call("openStoryInfo",new Class<?>[]{HakoParser.Link.class,boolean.class},new HakoParser.Link(id,"Feature fixture",base),false);waitFor(()->find(activity.getWindow().getDecorView(),info.summary)!=null);
  check(find(activity.getWindow().getDecorView(),info.summary)!=null&&field("nativeReader")==null,"Discovery displays cached novel details rather than opening chapter one");check(s.book(id).current.equals(current)&&s.book(id).visits==0,"Opening information preserves reading anchor and does not mark visited");check(find(activity.getWindow().getDecorView(),"Đọc tiếp")==null&&field("currentList")!=null,"Story information has catalog and no resume button");
  screenshot("story-info.png");
  CountDownLatch blocked=new CountDownLatch(1);((ExecutorService)field("webIo")).execute(()->{blocked.countDown();try{release.await(12,TimeUnit.SECONDS);}catch(Exception ignored){}});blocked.await(2,TimeUnit.SECONDS);
  call("openChapter",new Class<?>[]{String.class,String.class},id,current);waitFor(()->field("nativeReader")!=null);
  check(field("nativeReader")!=null&&release.getCount()==1,"Cached reading completes while web executor remains blocked");NativeReader reader=(NativeReader)field("nativeReader");check(reader.remainingChapterText().equals("Còn 2 ch"),"Footer shows remaining text chapters rather than chapter percent");release.countDown();
  SystemClock.sleep(300);waitForIdleSync();check(reader.remainingChapterText().equals("Còn 2 ch"),"Snapshot updates preserve unfinished current chapter in unread footer");runOnMainSync(()->reader.setNotice("Đang kiểm tra thông báo riêng"));SystemClock.sleep(100);screenshot("reader-footer.png");
  call("settings",new Class<?>[]{});screenshot("settings.png");ScrollView settings=(ScrollView)field("settingsScroll");AlertDialog dialog=(AlertDialog)field("settingsDialog");View plus=find(dialog.getWindow().getDecorView(),"+");check(plus!=null&&find(dialog.getWindow().getDecorView(),"22.0 sp")!=null,"Settings has direct step controls");runOnMainSync(()->plus.performClick());waitForIdleSync();check(find(dialog.getWindow().getDecorView(),"22.5 sp")!=null,"Plus adjusts value while preserving existing half-sp step");call("settingsVolume",new Class<?>[]{int.class,KeyEvent.class},KeyEvent.KEYCODE_VOLUME_DOWN,new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_VOLUME_DOWN));waitFor(()->settings.getScrollY()>0);check(settings.getScrollY()>0&&find(dialog.getWindow().getDecorView(),"22.5 sp")!=null,"Volume navigates settings without changing value");runOnMainSync(()->dialog.dismiss());
  OperationTrace.Span scope=OperationTrace.begin("test.attribution");s.book(id);s.chapters(id);s.readable(current);OperationTrace.end(scope,"ok",0);JSONObject ops=OperationTrace.payload();JSONArray samples=ops.getJSONArray("samples");JSONObject last=samples.getJSONObject(samples.length()-1);check(last.getString("op").equals("test.attribution")&&last.getJSONArray("q").getInt(0)>0&&last.getJSONArray("cache").getInt(0)>0,"Query and cache work are attributed to the enclosing action");check(ops.getJSONObject("definitions").getString("read.open").contains("openChapter"),"Report maps operation codes back to source entry points");for(int n=0;n<80;n++){OperationTrace.Span trace=OperationTrace.begin("read.page");OperationTrace.end(trace,"ok",0);}check(OperationTrace.payload().getJSONArray("samples").length()==24&&OperationTrace.payload().toString().length()<18000,"Operation retention and payload are compact and bounded");check(!OperationTrace.payload().toString().contains("invalid.example")&&!OperationTrace.payload().toString().contains("Feature fixture"),"Operation tracing contains neither story URLs nor titles");
  runOnMainSync(()->activity.finish());SystemClock.sleep(400);waitForIdleSync();s.readChapter(current);s.position(id,current,13,0.25f);
  File archive=DataTransfer.export(ctx,true);try(ZipFile zip=new ZipFile(archive)){check(zip.getEntry("db/hako.db")!=null&&zip.getEntry("chapters/"+current+"/content.html")!=null,"Full transfer contains database and downloaded chapter");check(zip.getEntry("manifest.json")!=null&&zip.getEntry("preferences.json")!=null&&zip.getEntry("cookies.sqlite")==null,"Transfer includes preferences without browser login cookies");}
  s.clearDownloaded(id);check(!s.html(current).exists()&&s.book(id)!=null&&s.book(id).current.equals(current)&&s.wasRead(current)&&s.book(id).pinned&&s.isKeepFull(id),"Delete removes downloaded content and preserves novel progress favorite and full choice");check(s.downloadsSuppressed(id)&&!s.needsReadingDownload(id),"Deleted content is not immediately restored by automatic prefetch");s.allowDownloads(id);check(!s.downloadsSuppressed(id),"Explicit download can restore deleted novel content");
  boolean rejected=false;try{DataTransfer.restore(ctx);}catch(IOException e){rejected=true;}check(rejected&&s.book(id)!=null,"Transfer refuses to replace an existing device library");
  clearDatabase(s,ctx);DataTransfer.restore(ctx);check(s.book(id)!=null&&s.book(id).current.equals(current)&&s.wasRead(current)&&s.html(current).exists()&&s.readable(current),"Full transfer restores SQLite content and reading state on a fresh device");check(s.book(id).pos==13&&s.book(id).pinned&&!ctx.getSharedPreferences("diagnostics",0).getBoolean("auto",true),"Transfer keeps saved position favorite and manual-only reporting");
  LibraryState.refresh(ctx);call("frequentList",new Class<?>[]{boolean.class},false);waitForIdleSync();check(find(activity.getWindow().getDecorView(),s.unread(id)+" chưa đọc")!=null,"Favorites highlight unread count instead of downloaded percentage");screenshot("favorites-progress.png");
  DataTransfer.export(ctx,false);clearDatabase(s,ctx);DataTransfer.restore(ctx);check(s.book(id)!=null&&s.wasRead(current)&&!s.html(current).exists()&&!s.chapter(id,current).ready,"Metadata-only transfer keeps progress but resets downloaded readiness");check(!new File(ctx.getFilesDir(),"validation-index.json").exists()||!s.readable(current),"Metadata-only restore cannot reuse downloaded-cache proof");
  FileOutputStream stream=new FileOutputStream(DataTransfer.archive(ctx));try(ZipOutputStream zip=new ZipOutputStream(stream)){zip.putNextEntry(new ZipEntry("../outside.txt"));zip.write(1);zip.closeEntry();}clearDatabase(s,ctx);rejected=false;try{DataTransfer.restore(ctx);}catch(IOException e){rejected=true;}check(rejected&&!new File(ctx.getFilesDir(),"outside.txt").exists(),"Transfer rejects path traversal before changing database");
  result.putString("stream","PASS TOTAL "+checks+" feature flow checks\n");finish(0,result);
 }catch(Throwable error){error.printStackTrace();result.putString("stream","FAIL "+error+"\n");finish(1,result);}finally{release.countDown();}}
 void screenshot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
 Object quietField(String name){try{return field(name);}catch(Exception e){throw new RuntimeException(e);}}
}

